<section class="container section"><p class="eyebrow">TUS CLIENTES</p><h1>Usuarios registrados.</h1><p><?= $total ?> <?= $total===1?'usuario':'usuarios' ?></p><form method="get" class="catalog-filters" role="search"><label class="search-field"><span class="sr-only">Buscar por nombre o correo</span><input type="search" name="q" value="<?= e($search) ?>" maxlength="100" placeholder="Buscar por nombre o correo"></label><button class="btn small">Buscar ↗</button><a class="text-link" href="/admin/usuarios">Limpiar</a></form>
<?php if(!$customers): ?><div class="empty"><h2>No hay usuarios para mostrar.</h2></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Teléfono</th><th>Dirección</th><th>Registro</th><th>Pedidos</th></tr></thead><tbody><?php foreach($customers as $customer): ?><tr><td><?= e($customer['name']) ?></td><td><?= e($customer['email']) ?></td><td><?= e(($customer['phone']??'')?:'Sin completar') ?></td><td><?php if(($customer['street']??'')!==''): ?><?= e($customer['street'].' '.$customer['street_number']) ?><small><?= e($customer['apartment']) ?></small><?php endif ?><small><?= e(implode(' · ',array_filter([$customer['city']??'',$customer['province']??'',$customer['postal_code']??'']))) ?></small></td><td><?= date('d/m/Y',strtotime($customer['created_at'])) ?></td><td><?= (int)$customer['order_count'] ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php if($total>25): ?><nav class="pagination" aria-label="Páginas de usuarios"><?php if($page>1): ?><a class="btn secondary small" href="?<?= e(http_build_query(['q'=>$search,'pagina'=>$page-1])) ?>">← Anterior</a><?php endif ?><span><?= $page ?> / <?= (int)ceil($total/25) ?></span><?php if($page*25<$total): ?><a class="btn secondary small" href="?<?= e(http_build_query(['q'=>$search,'pagina'=>$page+1])) ?>">Siguiente →</a><?php endif ?></nav><?php endif ?></section>
